export interface PlanningClient {
  query(input: PlanningQueryInput): Promise<PlanningSnapshot>;
  taskDetail(input: TaskDetailQueryInput): Promise<TaskDetailSnapshot>;
  mutate(input: PlanningMutationInput): Promise<PlanningMutationResult>;
}

export interface HomeClient {
  home(input: HomeQueryInput): Promise<HomeSnapshot>;
  doctor(input: DoctorQueryInput): Promise<DoctorReport>;
  repair(input: RepairInput): Promise<RepairResult>;
  bootstrapOrganizer(input: OrganizerBootstrapInput): Promise<OrganizerBootstrapResult>;
}

function actionTargetsIntent(
  action: AllowedAction,
  intent: PlanningMutationIntent,
): boolean {
  switch (intent.type) {
    case "project.create":
      return action.targetId === null;
    case "project.update":
      return action.targetId === intent.projectId;
    case "project.pause":
    case "project.resume":
    case "project.emergency-stop.prepare":
    case "project.emergency-stop.confirm":
      return action.targetId === intent.projectId;
    case "epic.create":
      return action.targetId === intent.projectId;
    case "epic.update":
      return action.targetId === intent.epicId;
    case "task.create":
      return action.targetId === intent.projectId || action.targetId === intent.workspaceId;
    case "task.update":
    case "task.launch-now":
      return action.targetId === intent.taskId;
    case "task.cancel":
      return action.targetId === intent.runId;
    case "dependency.add":
    case "dependency.remove":
    case "dependency.override":
      return action.targetId === intent.dependencyId;
    case "configuration.preview":
    case "configuration.apply":
      return action.targetId === intent.target.id;
  }
}

export function bindPlanningMutation(
  action: AllowedAction,
  intent: PlanningMutationIntent,
): PlanningMutationInput {
  if (action.kind !== intent.type) {
    throw new Error("planning action and intent do not match");
  }
  if (!actionTargetsIntent(action, intent)) {
    throw new Error("planning action and intent target do not match");
  }
  return planningMutationInputSchema.parse({
    schemaVersion: PLANNING_SCHEMA_VERSION,
    contractVersion: PLANNING_CONTRACT_VERSION,
    contractHash: PLANNING_CONTRACT_SHA256,
    requestId: action.requestId,
    idempotencyKey: action.idempotencyKey,
    expectedVersion: action.expectedVersion,
    humanApprovalRef: action.humanApprovalRef,
    acknowledgementRevision: action.acknowledgementRevision,
    intent,
  });
}
